// Applies Mike's changes to the generated iOS project (ios/ is regenerated by
// `npx cap add ios` and not committed; README.md, "Native shell hardening").
// Safe to run again: each change checks whether it is already there.
//
//   - Info.plist: the mike:// URL scheme and the permission prompts for
//     dictation (microphone; speech recognition, asked only on iOS before 26)
//     and the scanner (camera, photos), and audio in the background for
//     read-aloud.
//   - SceneDelegate: a native cover over the window whenever the app leaves
//     the foreground, so the app switcher's snapshot never shows matter
//     content (CSS alone can lose that race). A personal build may show the
//     real snapshot instead: MIKE_APP_SWITCHER_PREVIEW=1 at configure time
//     sets Info.plist's MikeAppSwitcherPreview, which the cover checks. Firm
//     builds leave it unset.
//   - AppDelegate: the app's Documents and Library excluded from iCloud and
//     Finder backups.
import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";

const app = new URL("../ios/App/App/", import.meta.url).pathname;
const plist = `${app}Info.plist`;
const buddy = (command, quiet = false) =>
  execFileSync("/usr/libexec/PlistBuddy", ["-c", command, plist], {
    encoding: "utf8",
    stdio: ["ignore", "pipe", quiet ? "ignore" : "inherit"],
  });
const has = (key) => {
  try {
    buddy(`Print :${key}`, true);
    return true;
  } catch {
    return false;
  }
};

const strings = {
  NSMicrophoneUsageDescription: "Mike uses the microphone when you dictate a message.",
  NSSpeechRecognitionUsageDescription: "Mike turns your dictation into text on this iPhone. The recording never leaves it.",
  NSCameraUsageDescription: "Mike uses the camera when you scan a document.",
  NSPhotoLibraryUsageDescription: "Mike opens your photo library when you choose a picture to attach.",
  NSPhotoLibraryAddUsageDescription: "Mike saves pictures to your photo library when you ask it to.",
};
for (const [key, value] of Object.entries(strings)) {
  if (has(key)) buddy(`Set :${key} ${value}`);
  else buddy(`Add :${key} string ${value}`);
}
// Read-aloud keeps playing when the app goes to the background or the phone
// locks: one audio element in the web view, with lock-screen controls.
if (!has("UIBackgroundModes")) buddy("Add :UIBackgroundModes array");
if (!/^\s*audio$/m.test(buddy("Print :UIBackgroundModes", true))) buddy("Add :UIBackgroundModes: string audio");
if (!has("CFBundleURLTypes")) {
  buddy("Add :CFBundleURLTypes array");
  buddy("Add :CFBundleURLTypes:0 dict");
  buddy("Add :CFBundleURLTypes:0:CFBundleURLName string com.firm.mike");
  buddy("Add :CFBundleURLTypes:0:CFBundleURLSchemes array");
  buddy("Add :CFBundleURLTypes:0:CFBundleURLSchemes:0 string mike");
}

// Whether the app switcher may show the app's real snapshot (see above).
const preview = process.env.MIKE_APP_SWITCHER_PREVIEW === "1";
if (has("MikeAppSwitcherPreview")) buddy(`Set :MikeAppSwitcherPreview ${preview}`);
else buddy(`Add :MikeAppSwitcherPreview bool ${preview}`);

function patch(file, marker, apply) {
  const path = `${app}${file}`;
  const source = readFileSync(path, "utf8");
  if (source.includes(marker)) return;
  const next = apply(source);
  if (next === source) throw new Error(`could not patch ${file}`);
  writeFileSync(path, next);
}

patch("SceneDelegate.swift", "MIKE_PRIVACY_COVER", (source) =>
  source.replace(
    /\n}\s*$/,
    `

    // MIKE_PRIVACY_COVER: hide the window's content while the app is not in
    // the foreground, before iOS takes the app switcher's snapshot.
    private var privacyCover: UIView?

    func sceneWillResignActive(_ scene: UIScene) {
        // MIKE_APP_SWITCHER_PREVIEW: a personal build may opt out.
        if Bundle.main.object(forInfoDictionaryKey: "MikeAppSwitcherPreview") as? Bool == true { return }
        guard let window = window, privacyCover == nil else { return }
        let cover = UIVisualEffectView(effect: UIBlurEffect(style: .systemMaterial))
        cover.frame = window.bounds
        cover.autoresizingMask = [.flexibleWidth, .flexibleHeight]
        window.addSubview(cover)
        privacyCover = cover
    }

    func sceneDidBecomeActive(_ scene: UIScene) {
        privacyCover?.removeFromSuperview()
        privacyCover = nil
    }
}
`,
  ),
);

// Projects configured before the opt-out existed have the cover without it.
patch("SceneDelegate.swift", "MIKE_APP_SWITCHER_PREVIEW", (source) =>
  source.replace(
    "        guard let window = window, privacyCover == nil else { return }",
    `        // MIKE_APP_SWITCHER_PREVIEW: a personal build may opt out.
        if Bundle.main.object(forInfoDictionaryKey: "MikeAppSwitcherPreview") as? Bool == true { return }
        guard let window = window, privacyCover == nil else { return }`,
  ),
);

patch("AppDelegate.swift", "MIKE_BACKUP_EXCLUSION", (source) =>
  source
    .replace(
      "        // Override point for customization after application launch.\n        return true",
      "        excludeAppDataFromBackup()\n        return true",
    )
    .replace(
      /\n}\s*$/,
      `

    // MIKE_BACKUP_EXCLUSION: session material and cached pages stay off
    // iCloud and Finder backups.
    private func excludeAppDataFromBackup() {
        let fm = FileManager.default
        let roots = fm.urls(for: .documentDirectory, in: .userDomainMask)
            + fm.urls(for: .libraryDirectory, in: .userDomainMask)
        for root in roots {
            var url = root
            var values = URLResourceValues()
            values.isExcludedFromBackup = true
            try? url.setResourceValues(values)
        }
    }
}
`,
    ),
);
console.log("ios configured");
